export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  thresholds,
  generatedAt = new Date().toISOString()
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholds && Object.keys(thresholds).length > 0) {
    const metricMap = new Map(evaluations.map((m) => [m.id, m]));

    for (const metricId of Object.keys(thresholds)) {
      if (!metricMap.has(metricId)) {
        throw new Error(`Unknown metric: ${metricId}`);
      }
    }

    const thresholdResults = [];
    let allPassed = true;

    for (const [metricId, min] of Object.entries(thresholds)) {
      const metric = metricMap.get(metricId);
      const passed = metric.score !== null && metric.score >= min;

      if (!passed) {
        allPassed = false;
      }

      thresholdResults.push({
        metric: metricId,
        min,
        score: metric.score,
        passed
      });
    }

    report.passed = allPassed;
    report.thresholds = thresholdResults;
  }

  return report;
}

