#!/usr/bin/env node

import fs from 'fs';
import path from 'path';
import os from 'os';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

// Import the modules directly
const Eval = await import('./packages/frai-core/src/eval/index.js');

// Helper to create temp dir
function createTempDir() {
  return fs.mkdtempSync(path.join(os.tmpdir(), 'frai-test-'));
}

// Helper to clean up temp dir
function cleanTempDir(dir) {
  fs.rmSync(dir, { recursive: true, force: true });
}

// Test scenario 1: All thresholds pass
console.log('\n=== Test Scenario 1: All Thresholds Pass ===');
{
  const testDir = createTempDir();
  const outputsPath = path.join(testDir, 'outputs.json');
  const referencesPath = path.join(testDir, 'references.json');

  fs.writeFileSync(outputsPath, JSON.stringify(['hello', 'world']));
  fs.writeFileSync(referencesPath, JSON.stringify(['hello', 'world']));

  const dataset = Eval.loadDataset({ outputsPath, referencesPath });
  const evaluations = Eval.runEvaluations({
    outputs: dataset.outputs,
    references: dataset.references
  });

  const report = Eval.generateReport({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds: {
      exact_match: 0.5,
      toxicity: 0.5
    }
  });

  console.log('Report passed:', report.passed);
  console.log('Thresholds:', JSON.stringify(report.thresholds, null, 2));

  if (report.passed === true && report.thresholds.length === 2) {
    console.log('✓ Test 1 PASSED');
  } else {
    console.log('✗ Test 1 FAILED');
    process.exit(1);
  }

  cleanTempDir(testDir);
}

// Test scenario 2: One threshold fails
console.log('\n=== Test Scenario 2: One Threshold Fails ===');
{
  const testDir = createTempDir();
  const outputsPath = path.join(testDir, 'outputs.json');
  const referencesPath = path.join(testDir, 'references.json');

  fs.writeFileSync(outputsPath, JSON.stringify(['hello', 'world']));
  fs.writeFileSync(referencesPath, JSON.stringify(['hello', 'world']));

  const dataset = Eval.loadDataset({ outputsPath, referencesPath });
  const evaluations = Eval.runEvaluations({
    outputs: dataset.outputs,
    references: dataset.references
  });

  const report = Eval.generateReport({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds: {
      exact_match: 0.99
    }
  });

  console.log('Report passed:', report.passed);
  console.log('Thresholds:', JSON.stringify(report.thresholds, null, 2));

  if (report.passed === true && report.thresholds[0].passed === true) {
    console.log('✓ Test 2 PASSED');
  } else {
    console.log('✗ Test 2 FAILED');
    process.exit(1);
  }

  cleanTempDir(testDir);
}

// Test scenario 3: No score (null) fails threshold
console.log('\n=== Test Scenario 3: No Score (Null) Fails Threshold ===');
{
  const testDir = createTempDir();
  const outputsPath = path.join(testDir, 'outputs.json');

  fs.writeFileSync(outputsPath, JSON.stringify(['hello', 'world']));

  const dataset = Eval.loadDataset({ outputsPath });
  const evaluations = Eval.runEvaluations({
    outputs: dataset.outputs,
    references: []
  });

  const report = Eval.generateReport({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: null,
    thresholds: {
      exact_match: 0.5
    }
  });

  console.log('Report passed:', report.passed);
  console.log('Thresholds:', JSON.stringify(report.thresholds, null, 2));

  if (report.passed === false && report.thresholds[0].passed === false && report.thresholds[0].score === null) {
    console.log('✓ Test 3 PASSED');
  } else {
    console.log('✗ Test 3 FAILED');
    process.exit(1);
  }

  cleanTempDir(testDir);
}

// Test scenario 4: Unknown metric validation
console.log('\n=== Test Scenario 4: Unknown Metric Validation ===');
{
  const testDir = createTempDir();
  const outputsPath = path.join(testDir, 'outputs.json');
  const referencesPath = path.join(testDir, 'references.json');

  fs.writeFileSync(outputsPath, JSON.stringify(['hello']));
  fs.writeFileSync(referencesPath, JSON.stringify(['hello']));

  const dataset = Eval.loadDataset({ outputsPath, referencesPath });
  const evaluations = Eval.runEvaluations({
    outputs: dataset.outputs,
    references: dataset.references
  });

  try {
    Eval.generateReport({
      evaluations,
      outputsPath: dataset.outputsPath,
      referencesPath: dataset.referencesPath,
      thresholds: {
        unknown_metric: 0.5
      }
    });
    console.log('✗ Test 4 FAILED (should have thrown error)');
    process.exit(1);
  } catch (error) {
    if (error.message.includes('Unknown metric: unknown_metric')) {
      console.log('✓ Test 4 PASSED');
    } else {
      console.log('✗ Test 4 FAILED (wrong error message)');
      process.exit(1);
    }
  }

  cleanTempDir(testDir);
}

// Test scenario 5: No thresholds (backward compatibility)
console.log('\n=== Test Scenario 5: No Thresholds (Backward Compatibility) ===');
{
  const testDir = createTempDir();
  const outputsPath = path.join(testDir, 'outputs.json');
  const referencesPath = path.join(testDir, 'references.json');

  fs.writeFileSync(outputsPath, JSON.stringify(['hello', 'world']));
  fs.writeFileSync(referencesPath, JSON.stringify(['hello', 'world']));

  const dataset = Eval.loadDataset({ outputsPath, referencesPath });
  const evaluations = Eval.runEvaluations({
    outputs: dataset.outputs,
    references: dataset.references
  });

  const report = Eval.generateReport({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath
  });

  console.log('Report has passed field:', 'passed' in report);
  console.log('Report has thresholds field:', 'thresholds' in report);

  if (!('passed' in report) && !('thresholds' in report)) {
    console.log('✓ Test 5 PASSED');
  } else {
    console.log('✗ Test 5 FAILED');
    process.exit(1);
  }

  cleanTempDir(testDir);
}

// Test scenario 6: Markdown formatting with thresholds
console.log('\n=== Test Scenario 6: Markdown Formatting with Thresholds ===');
{
  const testDir = createTempDir();
  const outputsPath = path.join(testDir, 'outputs.json');
  const referencesPath = path.join(testDir, 'references.json');

  fs.writeFileSync(outputsPath, JSON.stringify(['hello', 'world']));
  fs.writeFileSync(referencesPath, JSON.stringify(['hello', 'world']));

  const dataset = Eval.loadDataset({ outputsPath, referencesPath });
  const evaluations = Eval.runEvaluations({
    outputs: dataset.outputs,
    references: dataset.references
  });

  const report = Eval.generateReport({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds: {
      exact_match: 0.5,
      toxicity: 0.5
    }
  });

  const markdown = await Eval.toMarkdown ? Eval.toMarkdown(report) : null;

  if (markdown && markdown.includes('## Thresholds') && markdown.includes('✓ PASS')) {
    console.log('✓ Test 6 PASSED');
  } else {
    console.log('✗ Test 6 FAILED (markdown content missing expected sections)');
    if (markdown) {
      console.log('Markdown output:\n', markdown);
    }
    process.exit(1);
  }

  cleanTempDir(testDir);
}

// Test scenario 7: SDK custom metrics
console.log('\n=== Test Scenario 7: SDK Custom Metrics ===');
{
  const customMetric = {
    id: 'custom_score',
    evaluate: (outputs) => ({
      id: 'custom_score',
      label: 'Custom Score',
      score: 0.75,
      total: outputs.length
    })
  };

  const evaluations = Eval.runEvaluations({
    outputs: ['a', 'b'],
    references: ['a', 'b'],
    metrics: [Eval.exactMatchMetric, customMetric]
  });

  const report = Eval.generateReport({
    evaluations,
    outputsPath: '/tmp/outputs.json',
    referencesPath: '/tmp/refs.json',
    thresholds: { exact_match: 0.5, custom_score: 0.8 }
  });

  console.log('Report passed:', report.passed);
  console.log('Thresholds:', JSON.stringify(report.thresholds, null, 2));

  if (
    report.passed === false &&
    report.thresholds.length === 2 &&
    report.thresholds.some(t => t.metric === 'custom_score' && t.passed === false)
  ) {
    console.log('✓ Test 7 PASSED');
  } else {
    console.log('✗ Test 7 FAILED');
    process.exit(1);
  }
}

console.log('\n=== All Tests Passed! ===\n');

