    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath
  });

  if ('passed' in report) throw new Error('Should not have passed field when no thresholds provided');
  if ('thresholds' in report) throw new Error('Should not have thresholds field when no thresholds provided');

  cleanTempDir(testDir);
});

runTest('Test 6: Markdown Formatting with Thresholds', () => {
  const testDir = createTempDir();
  const outputsPath = path.join(testDir, 'outputs.json');
  const referencesPath = path.join(testDir, 'references.json');

  fs.writeFileSync(outputsPath, JSON.stringify(['hello', 'world']));
  fs.writeFileSync(referencesPath, JSON.stringify(['hello', 'world']));

  const dataset = Eval.loadDataset({ outputsPath, referencesPath });
  const evaluations = Eval.runEvaluations({
    outputs: dataset.outputs,
    references: dataset.references,
    metrics: [Eval.exactMatchMetric]
  });

  const report = Eval.generateReport({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds: { exact_match: 0.5 }
  });

  const markdown = Reporters.toMarkdown(report);

  if (!markdown.includes('## Thresholds')) throw new Error('Missing Thresholds section');
  if (!markdown.includes('✓ PASS')) throw new Error('Missing pass indicator');
  if (!markdown.includes('exact_match')) throw new Error('Missing metric name');

  cleanTempDir(testDir);
});

runTest('Test 7: SDK Custom Metrics', () => {
  const customMetric = {
    id: 'custom_score',
    evaluate: (outputs) => ({
      id: 'custom_score',
      label: 'Custom Score',
      score: 0.75,
      total: outputs.length
    })
  };

  const evaluations = Eval.runEvaluations({
    outputs: ['a', 'b'],
    references: ['a', 'b'],
    metrics: [Eval.exactMatchMetric, customMetric]
  });

  const report = Eval.generateReport({
    evaluations,
    outputsPath: '/tmp/outputs.json',
    referencesPath: '/tmp/refs.json',
    thresholds: { exact_match: 0.5, custom_score: 0.8 }
  });

  if (report.passed !== false) throw new Error('Expected report.passed to be false (custom_score 0.75 < 0.8)');
  if (report.thresholds.length !== 2) throw new Error('Expected 2 thresholds');

  const customThreshold = report.thresholds.find(t => t.metric === 'custom_score');
  if (!customThreshold) throw new Error('Missing custom_score threshold');
  if (customThreshold.passed !== false) throw new Error('Expected custom_score threshold to fail');
});

console.log(`\n${'='.repeat(50)}`);
console.log(`Tests Passed: ${testsPassed}`);
console.log(`Tests Failed: ${testsFailed}`);
console.log(`${'='.repeat(50)}\n`);

if (testsFailed > 0) {
  process.exit(1);
}

